     3→import { Toaster } from "sonner";
     4→import {
     5→  isServer,
     6→  QueryClient,
     7→  QueryClientProvider,
     8→} from "@tanstack/react-query";
     9→import { ReactQueryDevtools } from "@tanstack/react-query-devtools";
    10→import { ThemeProvider } from "next-themes";
    11→import type { PropsWithChildren } from "react";
    12→
    13→function makeQueryClient() {
    14→  return new QueryClient({
    15→    defaultOptions: {
    16→      queries: {
    17→        staleTime: 60 * 1000,
    18→      },
    19→    },
    20→  });
    21→}
    22→
    23→let browserQueryClient: QueryClient | undefined = undefined;
    24→
    25→function getQueryClient() {
    26→  if (isServer) {
    27→    return makeQueryClient();
    28→  }
    29→  browserQueryClient ??= makeQueryClient();
    30→  return browserQueryClient;
    31→}
    32→
    33→export const Providers = ({ children }: PropsWithChildren) => {
    34→  const queryClient = getQueryClient();
    35→
    36→  return (
    37→    <ThemeProvider attribute="class" defaultTheme="system" enableSystem>
    38→      <QueryClientProvider client={queryClient}>
    39→        <Toaster position="top-center" richColors />
    40→        {children}
    41→        {process.env.NODE_ENV === "development" && (
    42→          <ReactQueryDevtools initialIsOpen={false} />
    43→        )}
    44→      </QueryClientProvider>
    45→    </ThemeProvider>
    46→  );
    47→};
